import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        print("No common prefux exists")
        return

    first_line = data[0].split()
    n = int(first_line[0])

    if n == 0:
        print("No common prefux exists")
        return

    strings = []
    for i in range(1, n + 1):
        if i < len(data):
            strings.append(data[i].strip())

    if not strings:
        print("No common prefux exists")
        return

    odd_strings = []  # 1st, 3rd, 5th... (indices 0, 2, 4 in 0-based)
    even_strings = []  # 2nd, 4th, 6th... (indices 1, 3, 5 in 0-based)

    for i, s in enumerate(strings):
        if (i + 1) % 2 == 1:  # 1-indexed odd position
            odd_strings.append(s)
        else:
            even_strings.append(s)

    # Find LCP of all odd strings
    lcp = ""
    if odd_strings:
        lcp = odd_strings[0]
        for s in odd_strings[1:]:
            min_len = min(len(lcp), len(s))
            i = 0
            while i < min_len and lcp[i] == s[i]:
                i += 1
            lcp = lcp[:i]
            if not lcp:
                break

    # Find LCS (Longest Common Suffix) of all even strings
    lcs = ""
    if even_strings:
        lcs = even_strings[0]
        for s in even_strings[1:]:
            min_len = min(len(lcs), len(s))
            i = 1
            while i <= min_len and lcs[-i] == s[-i]:
                i += 1
            lcs = lcs[-(i-1):] if i > 1 else ""

    # Reverse the LCS to get the common prefix from reversed suffixes
    common_suffix_reversed = lcs[::-1]

    # Find the longest common prefix between lcp and common_suffix_reversed
    result = ""
    if lcp and common_suffix_reversed:
        min_len = min(len(lcp), len(common_suffix_reversed))
        i = 0
        while i < min_len and lcp[i] == common_suffix_reversed[i]:
            i += 1
        result = lcp[:i]

    if result:
        print(result)
    else:
        print("No common prefux exists")

if __name__ == "__main__":
    main()
